SELECT substatus, gendlbl, occulbl, seglabel, typelabel, 
    CASE WHEN ageval < 25 THEN '18-24' WHEN ageval < 35 THEN '25-34' WHEN ageval < 45 THEN '35-44' WHEN ageval < 55 THEN '45-54' WHEN ageval < 65 THEN '55-64' ELSE '65+' END as age_group,
    COUNT(*) FROM users GROUP BY substatus, gendlbl, occulbl, seglabel, typelabel, age_group ORDER BY COUNT(*) DESC LIMIT 10;

SELECT substatus, gendlbl, occulbl, 
    CASE WHEN ageval < 25 THEN '18-24' WHEN ageval < 35 THEN '25-34' WHEN ageval < 45 THEN '35-44' WHEN ageval < 55 THEN '45-54' WHEN ageval < 65 THEN '55-64' ELSE '65+' END as age_group,
    COUNT(*) FROM users GROUP BY substatus, gendlbl, occulbl, age_group HAVING COUNT(*) > 10 ORDER BY substatus, COUNT(*) DESC;
